import numpy as np

def feature(current, candidates, tour, start):
    """Negative Euclidean distance from current city to each candidate, scaled by the max candidate distance."""
    d = np.linalg.norm(candidates - current, axis=1)
    return -d / (d.max() + 1e-12)

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine of the angle between the incoming travel direction and the step to each candidate."""
    if tour.shape[0] < 2:
        return np.zeros(candidates.shape[0])
    dirv = current - tour[-2]
    vec = candidates - current
    nd = np.linalg.norm(dirv) + 1e-12
    nv = np.linalg.norm(vec, axis=1) + 1e-12
    return (vec @ dirv) / (nv * nd)

import numpy as np

def feature(current, candidates, tour, start):
    """Radial extremity of each candidate w.r.t. the centroid of the remaining cities, normalised."""
    cent = candidates.mean(axis=0)
    d = np.linalg.norm(candidates - cent, axis=1)
    return (d - d.mean()) / (d.max() + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Sum of the two smallest distances from each candidate to other unvisited cities, mean-centred and scaled by max."""
    k = candidates.shape[0]
    if k < 2:
        return np.zeros(k)
    diff = candidates[:, None, :] - candidates[None, :, :]
    d = np.sqrt(np.sum(diff * diff, axis=2))
    np.fill_diagonal(d, np.inf)
    part = np.partition(d, 1, axis=1)[:, :2]
    s = np.sum(np.where(np.isfinite(part), part, 0.0), axis=1)
    return (s - s.mean()) / (s.max() + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Travel-direction cosine of each candidate, gated by proximity (1 - d/dmax)."""
    k = candidates.shape[0]
    m = tour.shape[0]
    if m < 2:
        return np.zeros(k)
    v = tour[-1] - tour[-2]
    nv = np.linalg.norm(v)
    if nv < 1e-12:
        return np.zeros(k)
    step = candidates - current
    d = np.linalg.norm(step, axis=1)
    cos = (step @ v) / (d * nv + 1e-12)
    prox = 1.0 - d / (d.max() + 1e-12)
    return cos * prox

import numpy as np

def feature(current, candidates, tour, start):
    """Fraction of 24 fixed directions in which the candidate is the extreme (max-projection) point of the unvisited set."""
    k = candidates.shape[0]
    if k < 3:
        return np.zeros(k)
    angles = np.arange(24) * (2.0 * np.pi / 24.0)
    dirs = np.stack([np.cos(angles), np.sin(angles)], axis=1)  # (24, 2)
    proj = candidates @ dirs.T  # (k, 24)
    mx = proj.max(axis=0)  # (24,)
    return (proj >= mx - 1e-12).mean(axis=1)
